"""Canonical bounded acceptance; evidence regenerated by every successful run."""
import os,sys,subprocess,json
from pathlib import Path
R=Path(__file__).resolve().parent
BLENDER=os.environ.get('BLENDER','C:/Users/futur/AppData/Local/Programs/Blender-5.2.1/blender.exe')
NODE=os.environ.get('NODE','C:/Program Files/nodejs/node.exe')
os.environ['OPENBLAS_NUM_THREADS']='1'
steps=[]
def run(name,args):
 p=subprocess.run(args,cwd=R,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
 (R/(name+'-output.txt')).write_bytes(p.stdout)
 print(name, 'PASS' if p.returncode==0 else 'FAIL',flush=True)
 if p.returncode:print(p.stdout.decode('utf8',errors='replace'));raise SystemExit(p.returncode)
 steps.append({'check':name,'exit_code':p.returncode})
if '--skip-author' not in sys.argv:
 run('maps',[sys.executable,str(R/'maps.py')])
 run('author',[BLENDER,'--background','--factory-startup','--python-exit-code','1','--threads','2','--python',str(R/'author.py')])
run('build',[sys.executable,str(R/'build.py')])
for name in ['verify_source','verify_parity','verify_theme_source']:
 run(name,[BLENDER,'--background','--factory-startup','--python-exit-code','1','--threads','2','--python',str(R/(name+'.py'))])
run('motion',[NODE,str(R/'test_motion.mjs')])
for name in ['verify_browser','verify_extended']:
 run(name,[sys.executable,str(R/(name+'.py'))])
report={'status':'PASS','steps':steps,'html_bytes':(R/'mauritania-v1.html').stat().st_size,'glb_bytes':(R/'mauritania.glb').stat().st_size}
(R/'acceptance-check.json').write_text(json.dumps(report,indent=2))
print('HTML_BYTES',report['html_bytes'],'GLB_BYTES',report['glb_bytes'])
print('ALL ACCEPTANCE CHECKS PASS')
